import{I as n,o as c,c as d,j as a,a as s,J as i,w as l,b6 as u}from"./chunks/framework.BUXTSoD9.js";const h={style:{margin:"50px 0"}},f=JSON.parse('{"title":"Qué hacer cuando encuentras errores al escribir código - Guía práctica para preguntar a la IA con capturas de pantalla","description":"Aprende a preguntar eficientemente a la IA para resolver diversos errores de desarrollo, domina el flujo estándar de capturas de pantalla, descripción y localización de problemas, y convierte a la IA en tu asistente de depuración.","frontmatter":{"title":"Qué hacer cuando encuentras errores al escribir código - Guía práctica para preguntar a la IA con capturas de pantalla","description":"Aprende a preguntar eficientemente a la IA para resolver diversos errores de desarrollo, domina el flujo estándar de capturas de pantalla, descripción y localización de problemas, y convierte a la IA en tu asistente de depuración."},"headers":[],"relativePath":"es-es/stage-1/appendix-b-common-errors/index.md","filePath":"es-es/stage-1/appendix-b-common-errors/index.md"}'),m={name:"es-es/stage-1/appendix-b-common-errors/index.md"},v=Object.assign(m,{setup(g){const r="Aproximadamente <strong>30 minutos</strong>";return(b,e)=>{const o=n("ChapterIntroduction"),t=n("StepBar"),p=n("ClientOnly");return c(),d("div",null,[e[1]||(e[1]=a("h1",{id:"que-hacer-cuando-encuentras-errores-al-escribir-codigo",tabindex:"-1"},[s("Qué hacer cuando encuentras errores al escribir código "),a("a",{class:"header-anchor",href:"#que-hacer-cuando-encuentras-errores-al-escribir-codigo","aria-label":"Permalink to “Qué hacer cuando encuentras errores al escribir código”"},"​")],-1)),e[2]||(e[2]=a("h2",{id:"resumen-del-capitulo",tabindex:"-1"},[s("Resumen del capítulo "),a("a",{class:"header-anchor",href:"#resumen-del-capitulo","aria-label":"Permalink to “Resumen del capítulo”"},"​")],-1)),i(o,{duration:r,tags:["Técnicas de depuración","Colaboración con IA","Resolución de problemas","Herramientas de desarrollo"],coreOutput:"Un flujo estandarizado de resolución de errores",expectedOutput:"Poder resolver independientemente el 90% de los errores comunes"},{default:l(()=>[...e[0]||(e[0]=[a("p",null,"En la era de la IA, la forma de resolver errores ha cambiado.",-1),a("p",null,"No necesitas memorizar todos los tipos de errores, no necesitas ser un experto en depuración, ni siquiera necesitas entender qué significa el error.",-1),a("p",null,[a("strong",null,"Solo necesitas aprender una cosa: cómo preguntar a la IA.")],-1),a("p",null,[s("Este capítulo te enseñará un flujo de resolución "),a("strong",null,"de lo simple a lo avanzado"),s(":")],-1),a("ol",null,[a("li",null,[a("strong",null,"Paso 1: Pregunta directamente"),s(": Describe el síntoma + captura de pantalla, una sola frase")]),a("li",null,[a("strong",null,"Paso 2: Complementa información"),s(": Si no se puede resolver, abre F12 y añade información clave")])],-1),a("p",null,[s("Después de dominar este flujo, "),a("strong",null,"podrás resolver el 90% de los errores por tu cuenta"),s(".")],-1)])]),_:1}),e[3]||(e[3]=a("div",{class:"info custom-block"},[a("p",{class:"custom-block-title"},"Nota"),a("p",null,"Todos los métodos de este capítulo se basan en la experiencia real de uso de AI IDEs como Cursor/Trae/Claude, y pueden aplicarse directamente al desarrollo diario.")],-1)),a("div",h,[i(p,null,{default:l(()=>[i(t,{active:0,items:[{title:"Preguntar directamente",description:"Describe el síntoma + captura de pantalla"},{title:"Complementar información",description:"Abre F12 para localizar el problema"},{title:"Iterar hasta resolver",description:"Hasta que el problema se resuelva"}]})]),_:1})]),e[4]||(e[4]=u(`<h2 id="_1-metodo-central-pregunta-a-la-ia-con-capturas-de-pantalla" tabindex="-1">1. Método central: pregunta a la IA con capturas de pantalla <a class="header-anchor" href="#_1-metodo-central-pregunta-a-la-ia-con-capturas-de-pantalla" aria-label="Permalink to “1. Método central: pregunta a la IA con capturas de pantalla”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">¿Por qué es importante este capítulo?</p><p>La primera reacción de muchos principiantes al encontrar errores es:</p><ul><li>Entrar en pánico y empezar a modificar código al azar</li><li>Pasar media hora buscando &quot;cómo solucionar el error xxx&quot;</li><li>Intentar entender qué significa el error por sí mismos</li><li>Depurar solo hasta altas horas de la noche</li></ul><p><strong>Todo esto es perder el tiempo.</strong></p><p>En la era de la IA, la depuración se ha convertido en algo muy simple:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ver error → Captura de pantalla → Pregunta a la IA → Haz lo que dice la IA</span></span></code></pre></div><p>No necesitas entender el error, no necesitas saber depurar, ni siquiera necesitas saber dónde está el problema.</p><p><strong>Solo necesitas aprender cómo preguntar.</strong></p></div><h3 id="_1-1-la-forma-mas-simple-de-preguntar" tabindex="-1">1.1 La forma más simple de preguntar <a class="header-anchor" href="#_1-1-la-forma-mas-simple-de-preguntar" aria-label="Permalink to “1.1 La forma más simple de preguntar”">​</a></h3><p>No necesitas plantillas complejas, elige entre dos métodos:</p><p><strong>Método 1: Describe el síntoma</strong></p><p>Formato: qué hiciste, qué apareció ahora</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acabo de modificar el código de la página de login y ahora la página está en blanco, ¿qué hago?</span></span></code></pre></div><p><strong>Método 2: Captura de pantalla</strong></p><p>Haz una captura de pantalla directamente de la página actual o del mensaje de error</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[captura de pantalla]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>¿Cómo soluciono este error?</span></span></code></pre></div><p><strong>El mejor método: Descripción + captura de pantalla</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acabo de modificar el código de la página de login y ahora la página está en blanco.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[captura de pantalla]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>¿Qué hago?</span></span></code></pre></div><p><strong>Recuerda: describe claramente el contexto, añade una captura de pantalla, y la IA podrá ayudarte más rápido.</strong></p><h3 id="_1-2-como-explicar-el-problema-claramente" tabindex="-1">1.2 Cómo explicar el problema claramente <a class="header-anchor" href="#_1-2-como-explicar-el-problema-claramente" aria-label="Permalink to “1.2 Cómo explicar el problema claramente”">​</a></h3><p>Muchos principiantes saben que deben preguntar, pero no saben cómo expresarse. En realidad, solo necesitas explicar tres cosas:</p><p><strong>1. Qué acabas de hacer</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acabo de hacer clic en el botón guardar</span></span>
<span class="line"><span>Acabo de modificar el código de la página de login</span></span>
<span class="line"><span>Acabo de actualizar la página</span></span></code></pre></div><p><strong>2. Qué ves ahora</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ahora la página está en blanco</span></span>
<span class="line"><span>Ahora el botón no responde al hacer clic</span></span>
<span class="line"><span>Ahora muestra un mensaje de error</span></span></code></pre></div><p><strong>3. Qué efecto quieres lograr</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Quiero que los datos se guarden correctamente</span></span>
<span class="line"><span>Quiero que la página se muestre normalmente</span></span>
<span class="line"><span>Quiero que aparezca un aviso después de hacer clic en el botón</span></span></code></pre></div><p><strong>Ejemplo completo:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acabo de hacer clic en el botón guardar, y ahora la página muestra un error de &quot;error al guardar&quot;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[captura de pantalla]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Quiero que los datos del formulario se guarden correctamente en la base de datos, ¿qué debo hacer?</span></span></code></pre></div><p><strong>Principios clave:</strong></p><ul><li>Describe en lenguaje llano, sin terminología técnica</li><li>Sigue el orden cronológico: qué hiciste primero, qué pasó después</li><li>Expresa tu expectativa para que la IA sepa qué quieres</li></ul><h2 id="_2-paso-1-describe-el-sintoma-directamente" tabindex="-1">2. Paso 1: Describe el síntoma directamente <a class="header-anchor" href="#_2-paso-1-describe-el-sintoma-directamente" aria-label="Permalink to “2. Paso 1: Describe el síntoma directamente”">​</a></h2><p>Cuando encuentres un problema, <strong>no te apresures a abrir F12</strong>. Primero describe el síntoma, haz una captura de pantalla de la página actual y pásasela a la IA.</p><p>Muchas veces, la IA puede dar una solución directamente al ver la captura de pantalla.</p><h3 id="_2-1-como-describir-sintomas-comunes" tabindex="-1">2.1 Cómo describir síntomas comunes <a class="header-anchor" href="#_2-1-como-describir-sintomas-comunes" aria-label="Permalink to “2.1 Cómo describir síntomas comunes”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Simplemente describe</p><p><strong>Página en blanco</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>La página se abre en blanco, ¿qué hago?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[captura de pantalla]</span></span></code></pre></div><p><strong>El botón no responde al hacer clic</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Al hacer clic en este botón no pasa nada, ayúdame a revisar.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[captura de pantalla]</span></span></code></pre></div><p><strong>Los datos no se guardan</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hice clic en guardar, pero los datos no se guardaron, ¿qué hago?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[captura de pantalla]</span></span></code></pre></div><p><strong>El estilo no se muestra correctamente</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>El botón está desalineado, ¿cómo lo ajusto?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[captura de pantalla]</span></span></code></pre></div><p><strong>Error en la API</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>La llamada a la API da error, ayúdame a revisar.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[captura de pantalla]</span></span></code></pre></div></div><h3 id="_2-2-si-la-ia-lo-resuelve-directamente" tabindex="-1">2.2 Si la IA lo resuelve directamente <a class="header-anchor" href="#_2-2-si-la-ia-lo-resuelve-directamente" aria-label="Permalink to “2.2 Si la IA lo resuelve directamente”">​</a></h3><p>¡Felicidades, problema resuelto! Simplemente haz las modificaciones que indica la IA.</p><h3 id="_2-3-si-la-ia-dice-necesito-mas-informacion" tabindex="-1">2.3 Si la IA dice &quot;necesito más información&quot; <a class="header-anchor" href="#_2-3-si-la-ia-dice-necesito-mas-informacion" aria-label="Permalink to “2.3 Si la IA dice &quot;necesito más información&quot;”">​</a></h3><p>Entonces es cuando necesitas abrir F12 y complementar información clave. Sigue leyendo.</p><h2 id="_3-paso-2-complementa-informacion-clave" tabindex="-1">3. Paso 2: Complementa información clave <a class="header-anchor" href="#_3-paso-2-complementa-informacion-clave" aria-label="Permalink to “3. Paso 2: Complementa información clave”">​</a></h2><p>Cuando la IA dice que necesita más información, según el tipo de problema, abre F12 y captura el contenido correspondiente.</p><h3 id="_3-1-cuando-necesitas-complementar-informacion" tabindex="-1">3.1 Cuándo necesitas complementar información <a class="header-anchor" href="#_3-1-cuando-necesitas-complementar-informacion" aria-label="Permalink to “3.1 Cuándo necesitas complementar información”">​</a></h3><p>La IA podría responder así:</p><ul><li>&quot;Por favor, abre la Console a ver si hay errores&quot;</li><li>&quot;Haz una captura de pantalla del panel Network&quot;</li><li>&quot;Necesito ver el mensaje de error específico&quot;</li></ul><p>En ese caso, sigue las indicaciones de abajo para complementar las capturas.</p><h3 id="_3-2-complementar-informacion-de-console-pagina-en-blanco-errores" tabindex="-1">3.2 Complementar información de Console (página en blanco/errores) <a class="header-anchor" href="#_3-2-complementar-informacion-de-console-pagina-en-blanco-errores" aria-label="Permalink to “3.2 Complementar información de Console (página en blanco/errores)”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Pasos</p><p><strong>Paso 1: Presiona F12 para abrir las herramientas de desarrollo</strong></p><p>En Mac es <code>Cmd+Option+I</code>, o haz clic derecho en la página y selecciona &quot;Inspeccionar&quot;.</p><p><strong>Paso 2: Cambia a la pestaña Console</strong></p><p><strong>Paso 3: Haz una captura de pantalla de los errores en rojo</strong></p><p><strong>Paso 4: Envíalo a la IA</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Los errores de Console son los siguientes:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[captura de pantalla]</span></span></code></pre></div></div><h3 id="_3-3-complementar-informacion-de-network-problemas-de-datos-errores-de-api" tabindex="-1">3.3 Complementar información de Network (problemas de datos/errores de API) <a class="header-anchor" href="#_3-3-complementar-informacion-de-network-problemas-de-datos-errores-de-api" aria-label="Permalink to “3.3 Complementar información de Network (problemas de datos/errores de API)”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Pasos</p><p><strong>Paso 1: Presiona F12 para abrir las herramientas de desarrollo</strong></p><p><strong>Paso 2: Cambia a la pestaña Network</strong></p><p><strong>Paso 3: Repite la operación</strong> (haz clic en guardar/actualiza la página)</p><p><strong>Paso 4: Encuentra la petición correspondiente y haz una captura de pantalla</strong></p><ul><li>Mira la URL y el código de estado</li><li>Mira el Payload (parámetros enviados)</li><li>Mira el Response (resultado devuelto)</li></ul><p><strong>Paso 5: Envíalo a la IA</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>La información de Network es la siguiente:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Petición: [captura 1]</span></span>
<span class="line"><span>Parámetros: [captura 2]</span></span>
<span class="line"><span>Respuesta: [captura 3]</span></span></code></pre></div></div><h3 id="_3-4-complementar-informacion-de-elements-problemas-de-estilos" tabindex="-1">3.4 Complementar información de Elements (problemas de estilos) <a class="header-anchor" href="#_3-4-complementar-informacion-de-elements-problemas-de-estilos" aria-label="Permalink to “3.4 Complementar información de Elements (problemas de estilos)”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Pasos</p><p><strong>Paso 1: Clic derecho en el elemento → &quot;Inspeccionar&quot;</strong></p><p>Las herramientas de desarrollo se posicionarán automáticamente en ese elemento.</p><p><strong>Paso 2: Haz una captura de pantalla del panel Styles</strong></p><p><strong>Paso 3: Envíalo a la IA</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Los estilos del elemento son los siguientes:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[captura de pantalla]</span></span></code></pre></div></div><h2 id="_4-paso-3-itera-hasta-resolver" tabindex="-1">4. Paso 3: Itera hasta resolver <a class="header-anchor" href="#_4-paso-3-itera-hasta-resolver" aria-label="Permalink to “4. Paso 3: Itera hasta resolver”">​</a></h2><h3 id="_4-1-lo-que-no-debes-hacer" tabindex="-1">4.1 Lo que NO debes hacer <a class="header-anchor" href="#_4-1-lo-que-no-debes-hacer" aria-label="Permalink to “4.1 Lo que NO debes hacer”">​</a></h3><p>Estas acciones harán que pierdas tiempo:</p><p>Entrar en pánico al ver un error y empezar a modificar código al azar Pasar media hora buscando soluciones de errores Intentar entender el significado de cada error por tu cuenta Depurar solo hasta altas horas de la noche</p><h3 id="_4-2-lo-que-si-debes-hacer" tabindex="-1">4.2 Lo que SÍ debes hacer <a class="header-anchor" href="#_4-2-lo-que-si-debes-hacer" aria-label="Permalink to “4.2 Lo que SÍ debes hacer”">​</a></h3><p>Sigue este flujo:</p><p>Primero describe el síntoma y haz una captura de pantalla para preguntar Cuando la IA diga que necesita más información, abre F12 y complementa Modifica el código según las sugerencias Después de modificar, prueba; si el problema persiste, sigue haciendo capturas y preguntando</p><h2 id="_5-resumen-flujo-completo" tabindex="-1">5. Resumen: Flujo completo <a class="header-anchor" href="#_5-resumen-flujo-completo" aria-label="Permalink to “5. Resumen: Flujo completo”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Encuentras un problema</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Describe el síntoma directamente + captura de pantalla</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Pásalo a la IA: &quot;¿Qué hago?&quot;</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>¿La IA lo resolvió directamente?</span></span>
<span class="line"><span>    ↓ Sí</span></span>
<span class="line"><span>Haz lo que dice la IA</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Prueba si se resolvió</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>    ↓ No / La IA necesita más información</span></span>
<span class="line"><span>Abre F12 y complementa información clave</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Envíalo de nuevo a la IA</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Repite hasta resolver</span></span></code></pre></div>`,55))])}}});export{f as __pageData,v as default};
